  "backup.tipScope": "بیک اپ میں اس ٹیننٹ کے تمام ورک سپیس ماڈیول ریکارڈز، لک اپ فہرستیں، ترتیبات آبجیکٹس اور میسجنگ ڈیٹا شامل ہوتا ہے۔ آڈٹ ٹریل، اپ لوڈ شدہ فائلیں اور قطار میں پس منظر کے کام بحال نہیں ہوتے۔ سائن اِن پاس ورڈ سرور پر رہتے ہیں؛ ای میل اور Google کنکشن کے راز بھی رہتے ہیں اور بحال شدہ عوامی ترتیبات سے میل نہیں کھا سکتے جب تک دوبارہ منسلک نہ کریں۔",
